/*
 * PORTED, NEVER RE-DERIVED. Sources, in the product's repo:
 *   standingView                          -> src/lib/server/timeline/standing.ts
 *   paceView, parPoints                   -> src/lib/server/timeline/pace.ts
 *   trajectoryView, SCALE_MIN/MAX         -> src/lib/server/timeline/trajectory.ts
 *   ratingGeometry, scaleFraction         -> src/lib/format/rating.ts
 *   nextDated, nextLesson, the sentences  -> src/lib/components/course/WhereYoureAt.tsx
 *   the gauge's four marks + the goal-10   -> src/lib/components/course/RatingGauge.tsx
 *     collision rule
 * Proven equal to those functions over this fixture before it was pasted here:
 * same standing, same pace view, same par, same series, same geometry
 * (TASK-L159 AC, the L157 discipline).
 *
 * ONE code node for one calculation (doctrine 8). The counts, the pace and the
 * trajectory are three answers about ONE list of entries, and the second and
 * third are defined in terms of the first: `trajectoryView` TAKES the pace view
 * so the two panels cannot end up on two different windows. Splitting them
 * across three Functions would be three places a learner's programme could
 * disagree with itself.
 *
 * THE KIT DRAWS; THIS DECIDES. Every number a gauge or the pace SVG needs is
 * computed here and handed over as a fraction — `parPoints` included, which
 * `pace.ts` exports for exactly that reason. A renderer that rebuilt the par
 * rule would be a second owner of it.
 */
const SCALE_MIN = 1;
const SCALE_MAX = 10;
const DAY_MS = 86400000;

/* The words. One map, so a string table can replace them in one edit (i18n is
   still the port evaluation's open gap). From src/i18n/en/course.json. */
const COPY = {
  standingEyebrow: "Where you're at",
  counts: "You've finished {done} things on this programme, and {remaining} are still to come.",
  allDone: "You've finished all {done} things on this programme.",
  endsOn: 'You and your coach agreed to get there by {when}.',
  orderWithDate: 'The next thing with a date on it is {title}, {when} — start there, then pick the lesson up after it.',
  orderDateOnly: 'The next thing with a date on it is {title}, {when}.',
  orderLessonOnly: 'Pick up where you left off.',
  upNextAllDone: "You've worked through every concept on your path. Everything below is still here to revisit.",
  requiresSession: 'What your coach suggested you look at first',
  requiresAssignment: 'What it asks for',
  paceEyebrow: 'Your pace',
  aheadOne: 'You are one thing ahead of the pace for {when}.',
  aheadOther: 'You are {count} things ahead of the pace for {when}.',
  onPace: 'You are right on the pace for {when}.',
  shortOne: 'You are around one thing short of the pace for {when}.',
  shortOther: 'You are around {count} things short of the pace for {when}.',
  legendActual: "What you've done",
  legendPar: 'The pace for {when}',
  trajectoryEyebrow: 'How it is going',
  confidence: 'How you felt after each lesson',
  archivedLabel: '{label} — no longer on the list',
  goal: 'goal',
  gaugeAria: '{label}: {score} out of {scaleMax}. The goal you agreed is {target} out of {scaleMax}.',
  rowRated: '{label}: last rated {score} out of {scaleMax}, on {when}. The goal you agreed is {target} out of {scaleMax}.',
  rowUnrated: '{label}: not rated yet. The goal you agreed is {target} out of {scaleMax}.',
  pointTitle: '{score}/{scaleMax} · goal {target} · {when}\n\n{words}',
  earlierCaption: 'The faint marks are where you were. Select one to see that review.',
  earlierAria: 'Earlier: {score} out of {scaleMax}, against a goal of {target}, {when}. Select to open that review.'
};

function fill(s, values) {
  return String(s).replace(/\{(\w+)\}/g, (m, k) => (values[k] === undefined ? m : String(values[k])));
}

function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}

function clamp(n, lo, hi) {
  return n < lo ? lo : n > hi ? hi : n;
}

/* Clamp into [0,1], and treat a non-finite value as the low end. */
function unit(n) {
  if (!Number.isFinite(n)) return 0;
  return n < 0 ? 0 : n > 1 ? 1 : n;
}

/* ── standing.ts ────────────────────────────────────────────────────────────
   The unit is L60's: a completed path step, an answered brief, a coaching
   session that happened. A cancelled session is in NEITHER total, so a coach
   moving a meeting cannot move their client's "left to do" up; a withdrawn
   brief is off the programme. A submission is NOT counted separately — an
   assignment becomes done BY being answered, and counting both would move the
   number two for one action, dishonest in the direction that feels good.
   `total` is returned for the agreement check with the pace view and is
   DELIBERATELY NOT RENDERED: beside `done` it is one edit away from "6 of 12". */
function standingView(entries) {
  let total = 0;
  let done = 0;
  for (const e of entries) {
    switch (e.kind) {
      case 'lesson':
        total += 1;
        if (e.state === 'done') done += 1;
        break;
      case 'session':
        if (e.session && e.session.cancelledAt != null) break;
        total += 1;
        if (e.state === 'done') done += 1;
        break;
      case 'assignment':
        if (e.withdrawn) break;
        total += 1;
        if (e.answered) done += 1;
        break;
      default:
        break;
    }
  }
  if (total === 0) return null;
  return { done: done, remaining: total - done, total: total };
}

/* ── pace.ts ────────────────────────────────────────────────────────────────
   NULL WITHOUT A HORIZON, AND THAT IS THE WHOLE SAFETY PROPERTY. No agreed end
   and nothing booked means no deadline, and a pace line against a schedule
   nobody agreed to is the product inventing a deadline and then telling
   somebody they are behind it. The panel renders nothing at all.

   The agreed end WINS OUTRIGHT where there is one (L123 §4) and is read as the
   CLOSE of that day: `endsOn` is a calendar date, and midnight would make par
   reach the target at the start of the last day somebody was told they had. */
function paceView(entries, now, agreedEndsOn) {
  const nowMs = now.getTime();
  const agreed = !agreedEndsOn ? null : new Date(agreedEndsOn + 'T23:59:59.999Z').getTime();

  const countables = [];
  const anchors = [];
  let horizonMs = null;
  const note = (t) => {
    if (horizonMs === null || t > horizonMs) horizonMs = t;
  };

  /* A brief is dated by its FIRST submission: a revision is the same piece of
     work, not a second one. */
  const answeredAt = new Map();
  for (const e of entries) {
    if (e.kind !== 'submission' || e.source !== 'assignment') continue;
    if (e.assignmentId === null || e.at === null) continue;
    const t = new Date(e.at).getTime();
    const seen = answeredAt.get(e.assignmentId);
    if (seen === undefined || t < seen) answeredAt.set(e.assignmentId, t);
  }

  for (const e of entries) {
    switch (e.kind) {
      case 'lesson': {
        const doneAt = e.state === 'done' && e.at !== null ? new Date(e.at).getTime() : null;
        countables.push({ doneAt: doneAt });
        if (doneAt !== null) anchors.push(doneAt);
        break;
      }
      case 'session': {
        if (e.session && e.session.cancelledAt != null) break;
        const startsAt = new Date(e.session.startsAt).getTime();
        anchors.push(startsAt);
        note(startsAt);
        countables.push({ doneAt: e.state === 'done' ? startsAt : null });
        break;
      }
      case 'assignment': {
        if (e.withdrawn) break;
        if (e.dueAt !== null && e.dueAt !== undefined) note(new Date(e.dueAt).getTime());
        const doneAt = answeredAt.has(e.assignmentId) ? answeredAt.get(e.assignmentId) : null;
        countables.push({ doneAt: e.answered ? doneAt : null });
        if (doneAt !== null) anchors.push(doneAt);
        break;
      }
      default:
        break;
    }
  }

  const resolved = agreed !== null && Number.isFinite(agreed) ? agreed : horizonMs;
  if (resolved === null) return null;
  const horizon = resolved;

  const target = countables.length;
  if (target === 0) return null;

  const doneMoments = countables
    .map((c) => c.doneAt)
    .filter((t) => t !== null)
    .sort((a, b) => a - b);

  const earliest = anchors.length > 0 ? Math.min.apply(null, anchors) : nowMs;
  const start = Math.min(earliest, nowMs, horizon - DAY_MS);
  /* The window can run PAST the horizon, and that is the honest shape once a
     date has gone by: par flattens at the target while the actual line climbs.
     Nothing calls it overdue. */
  const windowEnd = Math.max(horizon, nowMs);
  const span = windowEnd - start;

  const at = (t) => clamp((t - start) / span, 0, 1);
  const horizonX = at(horizon);
  const nowX = at(nowMs);
  const parAt = (x) => (horizonX <= 0 ? target : target * clamp(x / horizonX, 0, 1));

  const done = doneMoments.length;
  const par = Math.round(parAt(nowX));

  const actual = [{ x: 0, done: 0 }];
  doneMoments.forEach((t, i) => {
    actual.push({ x: at(t), done: i + 1 });
  });
  actual.push({ x: nowX, done: done });

  return {
    startAt: new Date(start).toISOString(),
    horizonAt: new Date(horizon).toISOString(),
    target: target,
    done: done,
    par: par,
    delta: done - par,
    horizonX: horizonX,
    nowX: nowX,
    actual: actual
  };
}

/* The par line's own vertices, so the renderer draws rather than computes.
   Two segments once the horizon has passed — up to the target, then flat. */
function parPoints(view) {
  const rise = [
    { x: 0, done: 0 },
    { x: view.horizonX, done: view.target }
  ];
  return view.horizonX < 1 ? rise.concat([{ x: 1, done: view.target }]) : rise;
}

/* ── trajectory.ts ──────────────────────────────────────────────────────────
   A REQUIRED pace view, which is a safety property rather than an argument
   order: no horizon means no activity panel, and a trajectory floating on its
   own time axis is the second half of inventing a deadline.

   `words` is REQUIRED on a point. L126 refuses a rating whose event has no
   shared write-up at the WRITE; this is the read side of the same rule, and the
   words are the SHARED prose specifically — a number accompanied only by a note
   the learner cannot read is a number with no words as far as they are
   concerned. NO MOMENT, NO POINT: a rating's moment is its parent's, so an
   evaluation nobody has dated has nowhere on a time axis to be. */
function trajectoryView(entries, dimensions, pace) {
  const byDimension = new Map();
  const push = (ratings, moment, entryId, words) => {
    if (moment === null || moment === undefined) return;
    const prose = words ? String(words).trim() : '';
    if (prose === '') return;
    for (const r of ratings || []) {
      const point = { score: r.score, at: moment, entryId: entryId, words: prose };
      const listed = byDimension.get(r.dimensionId);
      if (listed) listed.push(point);
      else byDimension.set(r.dimensionId, [point]);
    }
  };

  const confidence = [];
  for (const e of entries) {
    switch (e.kind) {
      case 'session':
        push(e.ratings, e.at, e.id, e.session && e.session.summary);
        break;
      case 'evaluation':
        push(e.ratings, e.at, e.id, e.summary);
        break;
      case 'lesson':
        /* TWENTY-FIVE SPRINTS OF COLLECTED DATA, REACHING A SURFACE. Only a
           step with a moment, which is only a COMPLETE one. */
        if (e.confidence !== null && e.confidence !== undefined && e.at !== null) {
          confidence.push({ score: e.confidence, at: e.at, entryId: e.id, lesson: e.title });
        }
        break;
      default:
        break;
    }
  }

  const byTime = (a, b) => new Date(a.at).getTime() - new Date(b.at).getTime();
  const series = dimensions.map((d) => {
    const points = (byDimension.get(d.id) || []).slice().sort(byTime);
    const latest = points.length > 0 ? points[points.length - 1].score : null;
    return {
      dimensionId: d.id,
      label: d.label,
      target: d.target,
      points: points,
      latest: latest,
      /* The whole row wears --go once the LATEST judgement is at or above the
         agreed target: a state of the row rather than of each mark. */
      atTarget: latest !== null && latest >= d.target,
      archived: d.archivedAt !== null && d.archivedAt !== undefined
    };
  });
  confidence.sort(byTime);
  if (series.length === 0 && confidence.length === 0) return null;
  return { series: series, confidence: confidence };
}

/* ── format/rating.ts ───────────────────────────────────────────────────────
   Position and PROGRESS are two questions and only the second needs a target.
   Keeping them apart is what lets one gauge serve a row that has a goal and the
   confidence row, which must never grow one: a confidence gauge with an agreed
   goal would be the product setting a learner a target for how they ought to
   feel. It CLAMPS rather than refusing — a value we cannot draw honestly is
   drawn at the edge of what we can, never off the end of it. */
function scaleFraction(score) {
  return unit((score - SCALE_MIN) / (SCALE_MAX - SCALE_MIN));
}

function ratingGeometry(score, target) {
  const span = SCALE_MAX - SCALE_MIN;
  const scoreFraction = unit((score - SCALE_MIN) / span);
  const targetFraction = unit((target - SCALE_MIN) / span);
  return {
    scoreFraction: scoreFraction,
    targetFraction: targetFraction,
    /* Measured against the TARGET's position, not the top of the scale: the
       question is how close am I to what we agreed, and a learner whose goal is
       6 is not two-thirds of the way to it at 6. CLAMPED AT 1 — a 10 against a
       target of 6 is AT target, not more than there, and a fill that kept
       getting greener past the flag would congratulate a number rather than the
       agreement. */
    approach: targetFraction === 0 ? 1 : unit(scoreFraction / targetFraction),
    atTarget: Number.isFinite(score) && score >= target
  };
}

/* One owner for every date on this page, pinned to UTC (L93/L100). */
const FORMAT = new Intl.DateTimeFormat('en-GB', { timeZone: 'UTC', day: 'numeric', month: 'short', year: 'numeric' });
const fmtDate = (iso) => (iso ? FORMAT.format(new Date(iso)) : '');

/* ── WhereYoureAt.tsx ───────────────────────────────────────────────────────
   The next DATED thing, in the order the model already put them — band first,
   then time — so this is the first not-yet-done dated entry in a list somebody
   else ordered, INCLUDING a brief whose date has gone by, which is still the
   thing to do and is shown plainly with its date. A cancelled meeting and a
   withdrawn brief are never it: leading with either sends somebody to something
   that is not happening. */
function nextDated(ordered) {
  for (const e of ordered) {
    if (e.state === 'done' || e.at === null) continue;
    if (e.kind === 'session' && !(e.session && e.session.cancelledAt != null)) return e;
    if (e.kind === 'assignment' && !e.withdrawn) return e;
  }
  return null;
}

/* The next lesson to open. A LOCKED step is never it — `LearnerHome`'s old
   rule was the first non-complete step, which can be locked, and its Start
   button linked straight to a 403. */
function nextLesson(ordered) {
  for (const e of ordered) {
    if (e.kind === 'lesson' && (e.status === 'available' || e.status === 'in_progress')) return e;
  }
  return null;
}

/* ── The assembly ───────────────────────────────────────────────────────────
   Three panels over ONE list, each ABSENT rather than empty when there is
   nothing to measure: no horizon, no pace panel; no dimension and no
   confidence, no trajectory panel. Absence is a rendering path here, not a
   branch somebody skipped. */
const entries = plain(Inputs.entries) || [];
const dimensions = plain(Inputs.dimensions) || [];
const endsOn = String(Inputs.endsOn || '') || null;
/* The ONE clock read on this page. `pace.ts` takes `now` as a parameter
   precisely so nothing downstream reads an ambient one; the page is where a
   real instant has to enter, and the product's own `CourseHome` does the same. */
const now = new Date();

/* The model's own order (TASK-L157), re-derived here only to ANSWER "what is
   next" — `nextDated` reads a list somebody else ordered. */
const STATE_RANK = { done: 0, now: 1, ahead: 2 };
const KIND_ORDER = ['evaluation', 'session', 'assignment', 'lesson', 'submission', 'message', 'note', 'signal'];
const KIND_RANK = new Map(KIND_ORDER.map((k, i) => [k, i]));
const ordered = entries.slice().sort((a, b) => {
  const band = STATE_RANK[a.state] - STATE_RANK[b.state];
  if (band !== 0) return band;
  const aDated = a.at === null ? 1 : 0;
  const bDated = b.at === null ? 1 : 0;
  if (aDated !== bDated) return aDated - bDated;
  if (a.at !== null && b.at !== null && a.at !== b.at) return a.at < b.at ? -1 : 1;
  if (a.position !== b.position) return a.position - b.position;
  const kind = (KIND_RANK.get(a.kind) || 0) - (KIND_RANK.get(b.kind) || 0);
  if (kind !== 0) return kind;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
});

const standing = standingView(entries);
const dated = nextDated(ordered);
const lesson = nextLesson(ordered);

/* TWO COUNTS IN A SENTENCE, NEVER A DENOMINATOR. `standing.total` is computed
   and deliberately never rendered: beside `done` it is one edit away from
   "6 of 12", which is §4's ban wearing a count's clothes. */
Outputs.hasStanding = standing !== null;
Outputs.countsSentence = !standing
  ? ''
  : fill(standing.remaining === 0 ? COPY.allDone : COPY.counts, { done: standing.done, remaining: standing.remaining });

/* The agreed end, when there is one. A DATE and nothing else — no countdown,
   no "N days left", and no sentence naming the learner as the cause of a gap. */
Outputs.hasEndsOn = endsOn !== null;
Outputs.endsOnSentence = endsOn === null ? '' : fill(COPY.endsOn, { when: fmtDate(endsOn + 'T12:00:00.000Z') });

const datedTitle = dated === null ? null : dated.kind === 'session' ? dated.session.title : dated.title;
const datedWhen = dated && dated.at ? fmtDate(dated.at) : null;
Outputs.orderSentence = !(dated || lesson)
  ? standing && standing.remaining === 0
    ? COPY.upNextAllDone
    : ''
  : dated && datedTitle && datedWhen
    ? lesson
      ? fill(COPY.orderWithDate, { title: datedTitle, when: datedWhen })
      : fill(COPY.orderDateOnly, { title: datedTitle, when: datedWhen })
    : COPY.orderLessonOnly;
/* One Text node renders this, so the flag follows the SENTENCE. The product
   draws two <p>s of the same class and only ever one of them. */
Outputs.hasOrder = Outputs.orderSentence !== '';

/* What the dated thing asks them to have looked at. For a session: the prep
   their coach chose, MINUS what they have already done — this is a to-do, not a
   report on them. For a brief: the criteria it names. Plain words in the same
   ink: no count of how many are done, no tick, no cross, no colour. */
const requires =
  dated === null
    ? []
    : dated.kind === 'session'
      ? (dated.session.prep || []).filter((p) => p.state !== 'done').map((p) => p.title)
      : dated.criteria || [];
/* Objects rather than bare strings: a Repeater binds an item's FIELDS to the
   row component's inputs by name, and a plain string has none. */
Outputs.requires = requires.map((title, i) => ({ id: 'requires-' + i, title: title }));
Outputs.hasRequires = requires.length > 0;
Outputs.requiresLabel = dated && dated.kind === 'session' ? COPY.requiresSession : COPY.requiresAssignment;

const pace = paceView(entries, now, endsOn);
Outputs.hasPace = pace !== null;
if (pace) {
  const when = fmtDate(pace.horizonAt);
  const ahead = pace.delta > 0;
  /* PERMITTED, because it is what was asked for: a factual statement about a
     schedule. BANNED, and absent from the map above: any sentence naming the
     learner as the cause or the failure. */
  Outputs.paceHeadline = ahead
    ? fill(pace.delta === 1 ? COPY.aheadOne : COPY.aheadOther, { count: pace.delta, when: when })
    : pace.delta === 0
      ? fill(COPY.onPace, { when: when })
      : fill(-pace.delta === 1 ? COPY.shortOne : COPY.shortOther, { count: -pace.delta, when: when });
  Outputs.paceView = pace;
  Outputs.parPoints = parPoints(pace);
  Outputs.legendActual = COPY.legendActual;
  Outputs.legendPar = fill(COPY.legendPar, { when: when });
} else {
  Outputs.paceHeadline = '';
  Outputs.paceView = null;
  Outputs.parPoints = [];
  Outputs.legendActual = '';
  Outputs.legendPar = '';
}

/* NO ACTIVITY PANEL, NO TRAJECTORY PANEL. `trajectoryView` takes the pace view
   itself rather than deriving a second window, so the two cannot disagree. */
const trajectory = pace ? trajectoryView(entries, dimensions, pace) : null;

/* One gauge, handed everything it needs as a fraction. The kit node positions
   marks; nothing in it computes a scale. */
function gaugeOf(spec) {
  const g = spec.score === null || spec.target === null ? null : ratingGeometry(spec.score, spec.target);
  return {
    score: spec.score,
    target: spec.target,
    goalLabel: COPY.goal,
    scale: true,
    scaleMin: SCALE_MIN,
    scaleMax: SCALE_MAX,
    variant: spec.variant,
    scoreFraction: spec.score === null ? 0 : scaleFraction(spec.score),
    targetFraction: g ? g.targetFraction : 0,
    /* The ONE input to colour, and it only ever improves: the ramp runs from
       the series ink to --go, never yellow→green. `--warm` is encouragement and
       human recording, and being short of a goal is neither. */
    approach: g ? g.approach : 0,
    atTarget: g ? g.atTarget : false,
    hasScore: spec.score !== null,
    hasTarget: spec.target !== null,
    /* THE HIGH END GIVES WAY TO THE FLAG, found by rendering rather than by
       reading: a target AT the top of the scale puts "GOAL 10" exactly where
       "10" is written, and two numbers in one place is worse than one number
       missing. The flag wins — it is the fact the reader came for, and it names
       the top of the scale anyway when it is standing there. */
    showHighEnd: !(g && g.targetFraction > 0.88),
    ariaLabel: spec.ariaLabel,
    title: spec.title,
    earlier: spec.earlier
  };
}

const rows = [];
if (trajectory) {
  for (const s of trajectory.series) {
    const latest = s.points.length > 0 ? s.points[s.points.length - 1] : null;
    /* THE ACCESSIBLE NAME SAYS IT LONG, AND THAT IS NOT A SECOND SENTENCE.
       "8/10" is read out as "eight slash ten", so the row spells the same three
       numbers in words. It carries no fact the visible mark does not. */
    const description =
      s.latest === null
        ? fill(COPY.rowUnrated, { label: s.label, target: s.target, scaleMax: SCALE_MAX })
        : fill(COPY.rowRated, {
            label: s.label,
            score: s.latest,
            target: s.target,
            scaleMax: SCALE_MAX,
            when: fmtDate(latest.at)
          });
    rows.push({
      id: s.dimensionId,
      /* The class the row wears, decided HERE rather than by the renderer: an
         archived dimension is quieter and never struck through, and which it is
         is a fact about the coach's list rather than about drawing. */
      rowClass: s.archived ? 'trajectory-row is-archived' : 'trajectory-row',
      /* An archived dimension is off the coach's list and STILL ON THE CHART:
         the ratings were really given, and dropping them would be the chart
         omitting points without saying so. Quieter, never struck through. */
      label: s.archived ? fill(COPY.archivedLabel, { label: s.label }) : s.label,
      archived: s.archived,
      gauge: gaugeOf({
        score: s.latest,
        target: s.target,
        variant: 'rating',
        ariaLabel: description,
        title: latest
          ? fill(COPY.pointTitle, {
              score: latest.score,
              target: s.target,
              scaleMax: SCALE_MAX,
              when: fmtDate(latest.at),
              words: latest.words
            })
          : '',
        earlier: s.points.slice(0, -1).map((p) => ({
          score: p.score,
          fraction: scaleFraction(p.score),
          title: fill(COPY.pointTitle, {
            score: p.score,
            target: s.target,
            scaleMax: SCALE_MAX,
            when: fmtDate(p.at),
            words: p.words
          }),
          ariaLabel: fill(COPY.earlierAria, { score: p.score, target: s.target, scaleMax: SCALE_MAX, when: fmtDate(p.at) })
        }))
      })
    });
  }

  /* The learner's own answer, on ITS OWN ROW and never repeated faintly inside
     each dimension: it is one line, it is not per dimension, and drawing it
     behind each of them would dress it up as a self-assessment against targets
     nobody asked them about. NO TARGET, and it must never grow one. */
  if (trajectory.confidence.length > 0) {
    const latest = trajectory.confidence[trajectory.confidence.length - 1];
    rows.push({
      id: 'confidence',
      label: COPY.confidence,
      rowClass: 'trajectory-row is-confidence',
      archived: false,
      gauge: gaugeOf({
        score: latest.score,
        target: null,
        variant: 'confidence',
        ariaLabel: COPY.confidence,
        title: latest.lesson + ' · ' + latest.score + ' · ' + fmtDate(latest.at),
        earlier: trajectory.confidence.slice(0, -1).map((p) => ({
          score: p.score,
          fraction: scaleFraction(p.score),
          title: p.lesson + ' · ' + p.score + ' · ' + fmtDate(p.at),
          ariaLabel: p.lesson + ' · ' + p.score + ' · ' + fmtDate(p.at)
        }))
      })
    });
  }
}

Outputs.hasTrajectory = trajectory !== null;
Outputs.trajectoryRows = rows;
/* The caption explains a mark that may not be on screen: a programme with one
   judgement per dimension has no earlier marks at all, and a line about them
   would be a line about nothing. */
const hasEarlier = rows.some((r) => r.gauge.earlier.length > 0);
Outputs.hasEarlier = hasEarlier;
Outputs.earlierCaption = hasEarlier ? COPY.earlierCaption : '';
Outputs.loaded();
